package com.ruoyi.medical.persistence;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.json.JsonMapper;
import java.util.*;
import javax.sql.DataSource;
import jakarta.servlet.http.HttpServletRequest;
import org.springframework.jdbc.core.JdbcTemplate;
import static com.ruoyi.medical.persistence.TaskRunActivityJournal.*;

/** Immutable N06 alias, separate from leased step reuse. Only a private proof of
 * exact current inputs and physically recovered original outputs can create it. */
@org.springframework.stereotype.Component
public final class TaskRunAssemblySuccessReuse {
 static final String ACTION="task.run.assembly-success.reused.v1";
 static final String MANIFEST=org.apache.commons.codec.digest.DigestUtils.sha256Hex("TASK_ASSEMBLY_SUCCESS_REUSE_V1:exact-original-four-object-family+check:private-semantic-proof:no-successor-dispatch-or-COMMIT");
 private final JdbcTemplate db;private final PermissionSchema json;
 private org.springframework.beans.factory.ObjectProvider<TaskCandidateAssemblyResumeReader> readers;
 private org.springframework.beans.factory.ObjectProvider<TaskRunActivityPreparation> runs;private TaskDeterministicExecution executions;
 @org.springframework.beans.factory.annotation.Autowired void ownership(org.springframework.beans.factory.ObjectProvider<TaskRunActivityPreparation> runs,TaskDeterministicExecution executions){this.runs=runs;this.executions=executions;}
 public TaskRunAssemblySuccessReuse(@org.springframework.beans.factory.annotation.Qualifier("masterDataSource")DataSource data,PermissionSchema json){db=new JdbcTemplate(data);db.setQueryTimeout(5);this.json=json;}
 @org.springframework.beans.factory.annotation.Autowired void reader(org.springframework.beans.factory.ObjectProvider<TaskCandidateAssemblyResumeReader> readers){this.readers=readers;}
 void prepare(HttpServletRequest http,com.ruoyi.medical.workflow.WorkflowProtocol.Reference ref)throws Exception {try(var owned=runs.getObject().withCurrent(http,ref,c->executions.enter(c,"N06",derived(ref.runId(),ACTION)))){readers.getObject().read(http,ref,proof->{save(proof);return Boolean.TRUE;});}}
 private void save(TaskCandidateAssemblyResumeReader.Reusable proof)throws Exception {
  proof.requireUnchanged();var source=proof.source();var p=source.successor();var old=read(db,json,p.admission(),p.runId());if(old.isPresent()){same(proof.originalReceiptSha256(),old.get().required("original_receipt_sha256").asText());same(proof.successorInputSha256(),old.get().required("input_sha256").asText());return;}
  for(String action:List.of(TaskCandidateAssemblyStageJournal.PREPARE,TaskCandidateAssemblyStageJournal.DISPATCH,TaskCandidateAssemblyStageJournal.PRODUCE,TaskCandidateAssemblyStageJournal.COMMIT))if(!db.queryForList("SELECT operation_id FROM operation_record WHERE tenant_id=? AND target_id=? AND operation_name=? LIMIT 1 FOR UPDATE",p.tenantId(),p.runId(),action).isEmpty())bad();
  var value=json.object().put("schema_version","1.0.0").put("kind","ORIGINAL_ASSEMBLY_SUCCESS_REUSE").put("stage_kind","N06").put("run_id",p.runId()).put("step_id",proof.successorStepId()).put("input_sha256",proof.successorInputSha256()).put("original_run_id",source.originalRunId()).put("original_receipt_id",proof.originalReceiptId()).put("original_receipt_sha256",proof.originalReceiptSha256());value.set("current_input",proof.current().input());same(hash(proof.current().input()),proof.successorInputSha256());value.set("source",source.pins());value.set("original_receipt",proof.originalReceipt());same(hash(proof.originalReceipt()),proof.originalReceiptSha256());
  String id=derived(p.runId(),ACTION);new TaskRunActivityJournal(db,json).write(p.admission(),p.projectId(),p.runId(),id,ACTION,ACTION+":"+p.runId(),p.runId(),hash(source.pins()),p.classification(),"1.0.0",MANIFEST,value);
  changed(db.update("INSERT INTO task_run_assembly_success_reuse(tenant_id,project_id,run_id,original_run_id,operation_id,receipt_json,receipt_sha256,schema_version,schema_manifest_sha256,created_by,created_at,classification) VALUES(?,?,?,?,?,?,?,'1.0.0',?,?,UTC_TIMESTAMP(6),?)",p.tenantId(),p.projectId(),p.runId(),source.originalRunId(),id,json.canonical(value),hash(value),MANIFEST,p.actorId(),p.classification()));proof.requireUnchanged();
 }
 static Optional<JsonNode> read(JdbcTemplate db,PermissionSchema json,EnterpriseAccess.Admission a,String run)throws Exception {
  var rows=db.queryForList("SELECT * FROM task_run_assembly_success_reuse WHERE tenant_id=? AND run_id=? LIMIT 2 FOR UPDATE",a.context().tenant_id(),run);if(rows.isEmpty())return Optional.empty();var row=one(rows);var parser=new JsonMapper();var value=parser.readTree(text(row,"receipt_json"));same(hash(value),text(row,"receipt_sha256"));same("1.0.0",text(row,"schema_version"));same(MANIFEST,text(row,"schema_manifest_sha256"));same(a.actorId(),text(row,"created_by"));same(run,value.required("run_id").asText());same(text(row,"original_run_id"),value.required("original_run_id").asText());same("1.0.0",value.required("schema_version").asText());same("ORIGINAL_ASSEMBLY_SUCCESS_REUSE",value.required("kind").asText());same(run,value.required("source").required("successor_run_id").asText());same(value.required("original_run_id"),value.required("source").required("original_run_id"));same(value.required("original_receipt_id"),value.required("source").required("original_receipt_id"));same(value.required("original_receipt_sha256"),value.required("source").required("original_receipt_sha256"));same("N06",value.required("stage_kind").asText());same(hash(value.required("current_input")),value.required("input_sha256").asText());same(run,value.required("current_input").required("run_id").asText());same(value.required("step_id"),value.required("current_input").required("step_id"));RunContinuationService.requireSuccessor(db,a,run);
  same(value,new TaskRunActivityJournal(db,json).read(a,text(row,"project_id"),run,text(row,"operation_id"),ACTION,ACTION+":"+run,run,hash(value.required("source")),text(row,"classification"),"1.0.0",MANIFEST).orElseThrow());
  var original=one(db.queryForList("SELECT * FROM operation_record WHERE tenant_id=? AND target_id=? AND operation_id=? AND operation_name=? AND state='COMPLETED' LIMIT 2 FOR UPDATE",a.context().tenant_id(),text(row,"original_run_id"),value.required("original_receipt_id").asText(),TaskCandidateAssemblyStageJournal.COMMIT));var originalRun=one(db.queryForList("SELECT replay_manifest,classification,created_by FROM task_run WHERE tenant_id=? AND project_id=? AND run_id=? AND status IN ('FAILED','CANCELLED') AND ended_at IS NOT NULL AND dispatch_closed_at IS NOT NULL LIMIT 2 FOR UPDATE",a.context().tenant_id(),text(row,"project_id"),text(row,"original_run_id")));same(a.actorId(),text(originalRun,"created_by"));same(text(row,"classification"),text(originalRun,"classification"));
  var witness=new TaskRunActivityJournal(db,json).read(a,text(row,"project_id"),text(row,"original_run_id"),text(original,"operation_id"),TaskCandidateAssemblyStageJournal.COMMIT,text(original,"idempotency_key"),TaskCandidateAssemblyAuthority.derived("ACTION",text(row,"original_run_id")),hash(parser.readTree(text(originalRun,"replay_manifest"))),text(row,"classification"),"1.0.0",TaskCandidateAssemblyStageJournal.MANIFEST).orElseThrow();same(value.required("original_receipt"),witness.required("receipt"));same(value.required("original_receipt_sha256").asText(),hash(witness.required("receipt")));same(hash(witness.required("body")),witness.required("receipt").required("receipt_sha256").asText());if(!witness.required("receipt").required("produced").required("ready").booleanValue())bad();
  return Optional.of(value);
 }
 private static String hash(JsonNode n)throws Exception{return com.ruoyi.medical.contracts.WireValues.sha256(ContentReadAuthorization.canonicalBytes(n));}
}
